create table if not exists public.erp_fiscal_razao_lancamentos(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,conta_bancaria_id uuid references public.erp_contas_bancarias(id),documento text,descricao text not null default '',debito numeric(18,2) not null default 0,credito numeric(18,2) not null default 0,criado_em timestamptz not null default now());
create index if not exists idx_fiscal_razao_empresa_conta on public.erp_fiscal_razao_lancamentos(empresa_id,conta_bancaria_id,criado_em);
create table if not exists public.erp_fiscal_documentos(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,pedido_origem text,datas_venda text,termo_legal text,anexo_digital boolean not null default false,desconto_nota boolean not null default false,criado_em timestamptz not null default now());
create table if not exists public.erp_fiscal_grupos_contabeis(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,codigo text not null,nome text not null,nivel integer not null,criado_em timestamptz not null default now(),unique(empresa_id,codigo));
create table if not exists public.erp_fiscal_estornos(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,documento_alvo text not null,data_estorno date not null,justificativa text not null,documento_estornado_id uuid,criado_em timestamptz not null default now());
alter table public.erp_fiscal_razao_lancamentos enable row level security;
alter table public.erp_fiscal_documentos enable row level security;
alter table public.erp_fiscal_grupos_contabeis enable row level security;
alter table public.erp_fiscal_estornos enable row level security;
create policy fiscal_razao_all on public.erp_fiscal_razao_lancamentos for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy fiscal_documentos_all on public.erp_fiscal_documentos for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy fiscal_grupos_all on public.erp_fiscal_grupos_contabeis for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy fiscal_estornos_all on public.erp_fiscal_estornos for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
grant select,insert,update,delete on public.erp_fiscal_razao_lancamentos,public.erp_fiscal_documentos,public.erp_fiscal_grupos_contabeis,public.erp_fiscal_estornos to authenticated;
create or replace function public.erp_fiscal_estornar_documento(p_documento text,p_data date,p_justificativa text) returns uuid language plpgsql security invoker set search_path=public as $$ declare e uuid; v uuid; begin e:=erp_current_empresa_id(); if e is null and not erp_is_master() then raise exception 'Empresa não identificada'; end if; if exists(select 1 from erp_fiscal_estornos where empresa_id=e and documento_alvo=p_documento) then raise exception 'Already Reversed Warning'; end if; insert into erp_fiscal_estornos(empresa_id,documento_alvo,data_estorno,justificativa) values(e,p_documento,p_data,p_justificativa) returning id into v; return v; end $$;
revoke all on function public.erp_fiscal_estornar_documento(text,date,text) from public,anon;
grant execute on function public.erp_fiscal_estornar_documento(text,date,text) to authenticated;